from sympy import symbols, integrate, diff, solve, Rational
import math

x = symbols("x", real=True)

def choose(rule, K, a, b, tol):
    if rule == 1:
        name, bound = "trapezoid", lambda n: K * (b - a)**3 / (12 * n**2)
    elif rule == 2:
        name, bound = "midpoint", lambda n: K * (b - a)**3 / (24 * n**2)
    else:
        name, bound = "Simpson", lambda n: K * (b - a)**5 / (180 * n**4)
    n = 1
    while bound(n) >= tol or (rule == 3 and n % 2 == 1):
        n = n + 1
    print(f"  {name}: n = {n} gives the bound {float(bound(n)):.3e} < {float(tol):g}")
    step = 1
    if rule == 3:
        step = 2
    if n > step:
        print(f"  n = {n - step} gives {float(bound(n - step)):.3e}, not small enough")

def oldlimits(k, c, n, a, b):
    u = x**k + c
    F = u**(n + 1) / (k * (n + 1))
    lo, hi = u.subs(x, a), u.subs(x, b)
    G = x**(n + 1) / (k * (n + 1))
    print(f"  u = {u}: limits {a}, {b} become {lo}, {hi}, and the integral is {G.subs(x, hi) - G.subs(x, lo)}")
    print(f"  check in x: {F.subs(x, b) - F.subs(x, a)}, while the trap's old limits give {G.subs(x, b) - G.subs(x, a)}")

def pole(p, a, b):
    F = -1 / (x - p)
    if a <= p <= b:
        print(f"  1/({x - p})^2 blows up at x = {p}, inside [{a}, {b}]: FTC2 doesn't apply")
        print(f"  the trap, F(b) - F(a) anyway: {F.subs(x, b) - F.subs(x, a)}, a negative area for a positive function")
    else:
        print(f"  1/({x - p})^2 is continuous on [{a}, {b}]: [-1/({x - p})] from {a} to {b} = {F.subs(x, b) - F.subs(x, a)}")

def endavg(c2, c1, c0, a, b):
    f = c2*x**2 + c1*x + c0
    print(f"  average (1/{b - a}) * {integrate(f, (x, a, b))} = {integrate(f, (x, a, b)) / (b - a)}")
    print(f"  the trap, (f(a) + f(b))/2 = {(f.subs(x, a) + f.subs(x, b)) / 2}")

def run(kind, nums):
    if kind == "choose":
        choose(nums[0], nums[1], nums[2], nums[3], nums[4])
    elif kind == "oldlimits":
        oldlimits(int(nums[0]), nums[1], int(nums[2]), nums[3], nums[4])
    elif kind == "pole":
        pole(nums[0], nums[1], nums[2])
    else:
        endavg(nums[0], nums[1], nums[2], nums[3], nums[4])

problems = [("oldlimits", ["3", "-1", "2", "1", "2"]), ("pole", ["0", "-1", "2"]), ("choose", ["1", "3", "0", "1", "0.001"]),
    ("choose", ["3", "24", "1", "2", "0.000001"]), ("endavg", ["1", "0", "0", "0", "3"]), ("pole", ["0", "1", "3"]),
    ("choose", ["2", "3", "0", "1", "0.001"]), ("endavg", ["0", "2", "1", "0", "4"]), ("oldlimits", ["2", "0", "1", "0", "1"])]
for i in range(len(problems)):
    kind, nums = problems[i]
    nums = [Rational(v) for v in nums]
    print(f"Problem {i + 1}: {kind} {nums}")
    run(kind, nums)

